import{_ as e,o as r,c as a,a0 as o}from"./chunks/framework.BQGW-Zpy.js";const m=JSON.parse('{"title":"Hedera Network Impact","description":"","frontmatter":{},"headers":[],"relativePath":"business/network-impact.md","filePath":"business/network-impact.md"}'),n={name:"business/network-impact.md"};function i(d,t,s,c,h,l){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="hedera-network-impact" tabindex="-1">Hedera Network Impact <a class="header-anchor" href="#hedera-network-impact" aria-label="Permalink to &quot;Hedera Network Impact&quot;">​</a></h1><h2 id="how-every-transfer-generates-on-chain-activity" tabindex="-1">How every transfer generates on-chain activity <a class="header-anchor" href="#how-every-transfer-generates-on-chain-activity" aria-label="Permalink to &quot;How every transfer generates on-chain activity&quot;">​</a></h2><p>Each transfer through this system produces a fixed, auditable burst of Hedera transactions, <strong>regardless of which chain actually settles the payment leg</strong>. Hedera is always the trust anchor.</p><table tabindex="0"><thead><tr><th>Event</th><th>Hedera transaction type</th><th>Count per transfer</th></tr></thead><tbody><tr><td>Compliance anchor (KYC/AML outcome)</td><td>HCS <code>TopicMessageSubmit</code></td><td>1</td></tr><tr><td>Quote anchor (FX rate + fee)</td><td>HCS <code>TopicMessageSubmit</code></td><td>1</td></tr><tr><td>Routing-decision anchor (why this chain)</td><td>HCS <code>TopicMessageSubmit</code></td><td>1</td></tr><tr><td>Settlement execution (Hedera-routed transfers only)</td><td>HTS <code>TransferTransaction</code></td><td>0 or 1</td></tr><tr><td>Completion schedule creation</td><td>HSS <code>ScheduleCreateTransaction</code></td><td>1</td></tr><tr><td>Completion signatures (source-side + destination-side partner)</td><td>HSS <code>ScheduleSignTransaction</code></td><td>2</td></tr><tr><td>Completion message (auto-executed once both sign)</td><td>HCS <code>TopicMessageSubmit</code>, via HSS</td><td>1</td></tr><tr><td>Mirror Node verification reads</td><td>Mirror Node REST calls</td><td>1–2</td></tr></tbody></table><p><strong>Minimum per transfer: 8 Hedera transactions</strong> (3 HCS anchors + the 5-transaction HSS completion sequence), plus 1 more if the settlement leg itself routes to Hedera.</p><p>This is non-trivial because the 3 HCS anchors and the full completion sequence happen for <em>every</em> transfer — even one that routes to Ethereum for settlement still anchors its compliance, quote, routing decision, and two-party completion on Hedera. The trust layer cannot be bypassed by the settlement-chain fallback.</p><hr><h2 id="tps-model-at-realistic-scale" tabindex="-1">TPS model at realistic scale <a class="header-anchor" href="#tps-model-at-realistic-scale" aria-label="Permalink to &quot;TPS model at realistic scale&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stage</th><th>Assumed transfers/day</th><th>Hedera txns/day</th><th>Peak TPS (16-hour window)</th></tr></thead><tbody><tr><td><strong>Pilot</strong> (one corridor, 3 active sending users)</td><td>10</td><td>80</td><td>0.001</td></tr><tr><td><strong>Early traction</strong> (3 corridors, freelancer platform partnership)</td><td>500</td><td>4,000</td><td>0.07</td></tr><tr><td><strong>Year 1 target</strong> (3 corridors, community + SME segment)</td><td>5,000</td><td>40,000</td><td>0.7</td></tr><tr><td><strong>Year 2 target</strong> (10 corridors, second sending market)</td><td>50,000</td><td>400,000</td><td>6.9</td></tr><tr><td><strong>Growth ceiling, SOM</strong> (≈0.01% of $176.5B SAM at avg. $300/transfer)</td><td>160,000</td><td>1,280,000</td><td>22.2</td></tr></tbody></table><p>At the SOM ceiling this project is a <strong>~22 TPS contributor</strong> to the Hedera network — meaningful, not dominant. The point is not volume leadership; it is a committed, recurring, high-value transaction stream (each burst carries compliance evidence AND a genuine two-party completion confirmation, not just a token move) from a segment of non-crypto users who would not otherwise interact with Hedera at all.</p><hr><h2 id="account-creation" tabindex="-1">Account creation <a class="header-anchor" href="#account-creation" aria-label="Permalink to &quot;Account creation&quot;">​</a></h2><p>The walletless design means end-users never create Hedera accounts — that is the product&#39;s core promise. Account growth therefore comes from the <strong>operator tier</strong>, not the consumer tier.</p><table tabindex="0"><thead><tr><th>Account type</th><th>When created</th><th>One-time or recurring</th></tr></thead><tbody><tr><td>Operator / treasury account</td><td>Once, at deployment</td><td>One-time</td></tr><tr><td>Per-corridor payout-partner account</td><td>Once per signed partner</td><td>One per corridor</td></tr><tr><td>Licensed on-ramp account</td><td>Once per on-ramp integration</td><td>One per integration</td></tr><tr><td>SME B2B API subscriber account</td><td>Once per B2B customer onboarded</td><td>Scales with B2B segment</td></tr><tr><td>Community-feature per-user account <em>(future)</em></td><td>Optionally, when a sender opts into the verified community</td><td>Scales with consumer volume</td></tr></tbody></table><p><strong>Year 1 realistic new accounts: 5–15</strong> (operator + 3 corridor partners + initial B2B customers). These are not consumer signups, but they are real, active accounts with recurring transaction volume — a higher-quality metric than dormant accounts.</p><p>The community-feature gate (a real Hedera anchor is required to earn a one-time posting code) could, in a future iteration, be reframed as a lightweight Hedera account for the sender — turning every verified sender into a new account holder without ever exposing a wallet to them. This is scoped as post-MVP work.</p><hr><h2 id="why-hedera-specifically-quantified" tabindex="-1">Why Hedera specifically, quantified <a class="header-anchor" href="#why-hedera-specifically-quantified" aria-label="Permalink to &quot;Why Hedera specifically, quantified&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Value for this use case</th></tr></thead><tbody><tr><td>HCS finality</td><td>~3s deterministic — the compliance timestamp is legally meaningful because it is not probabilistic</td></tr><tr><td>Per-message fee</td><td>Fixed USD-denominated fractions of a cent — the compliance anchor costs less than $0.001, so it is economically viable at all transfer sizes</td></tr><tr><td>Mirror Node public access</td><td>Anyone (regulator, auditor, counterparty) can verify without going through this project&#39;s own API</td></tr><tr><td>Stablecoin Studio</td><td>Path to MiCA-compliant stablecoin issuance on-chain, without a separate EMT issuer, once licensing is in place</td></tr><tr><td>TPS headroom</td><td>10,000+ TPS available vs. our ~22 TPS at SOM — no technical ceiling anywhere near this product&#39;s scale</td></tr></tbody></table><p>The binding constraint on network impact is <strong>partner agreement velocity</strong> (commercial), not network capacity (technical). See <a href="./go-to-market.html">Go-to-Market Strategy</a> and <a href="./business-model.html">Business Model</a>.</p>',20)])])}const p=e(n,[["render",i]]);export{m as __pageData,p as default};
